from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','badal-and-moti','Badal and Moti',
 ('A boy, a puppy and a muddy pit','Badal lives with his mother in a village. One evening he finds a shivering puppy by the road and brings it home. He names the puppy Moti. When Badal falls into a deep pit on a rainy day, it is Moti who finds him. In this chapter you will read the story, learn how past actions end in ed, learn about questions and statements, and put story events in order.'),
 [('The story of Badal and Moti',['Badal is a boy who lives with his mother in a village, and they are very happy.','One evening, when Badal is coming back from school, he sees a puppy shivering in the cold and brings it home.','His mother says the puppy can stay only if Badal promises to take care of it. Badal and his mother name the puppy Moti.','Moti grows up and loves Badal. They eat and play together, and Moti follows Badal everywhere.']),
  ('Badal falls into the pit',['One rainy day Badal slips on a muddy lane and falls into a deep pit. He tries hard but cannot climb out.','When Badal does not come home on time, his mother is worried and gathers the neighbours to search for him. Moti goes with them.','Moti catches Badal\'s scent, follows it to the pit and starts barking.','The barking tells the neighbours where Badal is. They pull him out with a rope, and Badal hugs Moti and thanks him.','The story shows that a pet who is cared for loves us and can help us when we need it.']),
  ('Words about things that already happened',['The words lived, loved, played, gathered and thanked all end with ed.','These words tell us about actions that have already happened. This is called the past.','To tell about the past we can often add ed to an action word: walk becomes walked, play becomes played, talk becomes talked, ask becomes asked and touch becomes touched.']),
  ('Questions and statements',['A sentence that asks something is a question, and it ends with a question mark (?).','A sentence that tells something is a statement, and it ends with a full stop (.).','Can this puppy stay with us? is a question. The sun rises in the east is a statement.','Every sentence begins with a capital letter.']),
  ('Putting a story in order',['A story has a beginning, a middle and an end. Events must be told in the order in which they happened.','In this story, Badal first finds the puppy, then names him Moti, then falls in the pit, then Moti barks, and last Badal hugs Moti.','In the pigeon and ant story, the dove drops a leaf to save the ant, and later the ant bites the hunter to save the dove.'])],
 [('Make past words: walk, play, ask.',[('The words are action words.','We add ed.'),('walk + ed = walked, play + ed = played, ask + ed = asked.','Each now tells about the past.'),('These actions have already happened.','So the ed word is in the past.')]),
  ('Put a ? or a . at the end: What is your name',[('The sentence asks something.','It is a question.'),('A question ends with a question mark.','So we write ?'),('What is your name?','This is the right sentence.')])],
 ('Tell the story of Badal and Moti in order.',['Badal finds a puppy','Names him Moti','Falls into a pit','Moti barks and people rescue him'],['Badal lived with his grandmother','Moti found Badal by his photo']),
 ['Badal finds a puppy and names him Moti.','Moti follows Badal\'s scent and saves him from the pit.','Past actions often end in ed.','Questions end with ?, statements end with a full stop.','Story events must be in the right order.'],
 [M('1',1,'What did Badal find by the roadside?','A shivering puppy',[('A kitten','It was a puppy'),('A bird','It was a puppy')],'Badal found a puppy shivering in the cold.'),
  M('2',1,'What was the puppy named?','Moti',[('Badal','Badal is the boy'),('Bholu','Not in the story')],'They named the puppy Moti.'),
  M('3',1,'Where did Badal fall?','Into a deep pit',[('Into a river','It was a pit'),('Off a tree','It was a pit')],'He slipped and fell into a deep pit.'),
  M('4',1,'How did Moti find Badal?','By his scent',[('By his photo','A dog cannot use a photo'),('By his voice on the phone','Not in the story')],'Moti followed Badal\'s scent.'),
  F('5',2,'Badal lived with his grandmother.',False,'He lived with his mother.'),
  F('6',2,'Moti barked near the pit.',True,'The barking alerted the neighbours.'),
  M('7',2,'Which word tells about the past?','Played',[('Play','This is the present form'),('Plays','This is the present form')],'Played ends with ed and tells about the past.'),
  M('8',2,'Which sentence is a question?','Whose shoes are these?',[('I like mangoes.','This is a statement'),('The sun rises in the east.','This is a statement')],'A question asks something and ends with ?.'),
  M('9',2,'What did Badal\'s mother say before the puppy could stay?','Badal must take care of it',[('Badal must sell it','Not in the story'),('Badal must give it a bath daily','Not in the story')],'She asked Badal to promise to care for the puppy.'),
  S('10',2,'Add ed to walk. What word do you get?',['walked','Walked'],'walk + ed = walked.'),
  M('11',3,'What comes first in the story?','Badal finds a puppy',[('Badal hugs Moti','This is last'),('Moti barks near the pit','This is near the end')],'The story begins with Badal finding the puppy.'),
  M('12',3,'Which mark ends the sentence "Brinda and Namrata are good friends"?','A full stop',[('A question mark','It is a statement'),('A comma','A sentence ends with a full stop')],'It tells something, so it ends with a full stop.')],
 keep=['past','question','statement'])
